// ---- Metrics: scrape kubelet/cAdvisor on every node ----
discovery.kubernetes "nodes" {
  role = "node"
}

prometheus.scrape "kubelet_cadvisor" {
  targets              = discovery.kubernetes.nodes.targets
  scheme               = "https"
  bearer_token_file    = "/var/run/secrets/kubernetes.io/serviceaccount/token"
  metrics_path         = "/metrics/cadvisor"
  job_name             = "integrations/kubernetes/cadvisor"
  scrape_interval      = "60s"

  tls_config {
    insecure_skip_verify = true
  }

  forward_to = [prometheus.relabel.cadvisor_filter.receiver]
}

prometheus.scrape "kubelet" {
  targets              = discovery.kubernetes.nodes.targets
  scheme               = "https"
  bearer_token_file    = "/var/run/secrets/kubernetes.io/serviceaccount/token"
  metrics_path         = "/metrics"
  job_name             = "integrations/kubernetes/kubelet"
  scrape_interval      = "60s"

  tls_config {
    insecure_skip_verify = true
  }

  forward_to = [prometheus.relabel.kubelet_filter.receiver]
}

// Trims cardinality to stay under the Grafana Cloud free-tier active-series cap.
// Source: github.com/grafana/k8s-monitoring-helm allowLists/cadvisor.yaml + its reference Alloy config.
prometheus.relabel "cadvisor_filter" {
  max_cache_size = 100000

  rule {
    source_labels = ["__name__"]
    regex         = "up|scrape_samples_scraped|container_cpu_cfs_periods_total|container_cpu_cfs_throttled_periods_total|container_cpu_cfs_throttled_seconds_total|container_cpu_usage_seconds_total|container_fs_reads_bytes_total|container_fs_reads_total|container_fs_writes_bytes_total|container_fs_writes_total|container_memory_cache|container_memory_rss|container_memory_swap|container_memory_usage_bytes|container_memory_working_set_bytes|container_network_receive_bytes_total|container_network_receive_packets_dropped_total|container_network_receive_packets_total|container_network_transmit_bytes_total|container_network_transmit_packets_dropped_total|container_network_transmit_packets_total|machine_memory_bytes"
    action        = "keep"
  }
  // Drop the empty-container/pause-container series cadvisor emits per cgroup
  // (github.com/google/cadvisor/issues/2688)
  rule {
    source_labels = ["__name__", "container"]
    separator     = "@"
    regex         = "(container_cpu_.*|container_fs_.*|container_memory_.*|container_pressure_.*)@"
    action        = "drop"
  }
  rule {
    source_labels = ["__name__", "image"]
    separator     = "@"
    regex         = "(container_cpu_.*|container_fs_.*|container_memory_.*|container_network_.*|container_pressure_.*)@"
    action        = "drop"
  }
  // Only keep filesystem series for real physical devices, not every loop/tmpfs mount
  rule {
    source_labels = ["__name__", "device"]
    separator     = "@"
    regex         = "container_fs_.*@(/dev/)?(mmcblk.p.+|nvme.+|rbd.+|sd.+|vd.+|xvd.+|dasd.+)"
    target_label  = "__keepme"
    replacement   = "1"
  }
  rule {
    source_labels = ["__name__", "__keepme"]
    separator     = "@"
    regex         = "container_fs_.*@"
    action        = "drop"
  }
  rule {
    source_labels = ["__name__"]
    regex         = "container_fs_.*"
    target_label  = "__keepme"
    replacement   = ""
  }
  // Only keep network series for real interfaces, not every veth pair k3s creates per pod
  rule {
    source_labels = ["__name__", "interface"]
    separator     = "@"
    regex         = "container_network_.*@(en[ospx][0-9].*|wlan[0-9].*|eth[0-9].*)"
    target_label  = "__keepme"
    replacement   = "1"
  }
  rule {
    source_labels = ["__name__", "__keepme"]
    separator     = "@"
    regex         = "container_network_.*@"
    action        = "drop"
  }
  rule {
    source_labels = ["__name__"]
    regex         = "container_network_.*"
    target_label  = "__keepme"
    replacement   = ""
  }

  forward_to = [prometheus.remote_write.grafana_cloud.receiver]
}

// Same as above, for kubelet. Source: allowLists/kubelet.yaml in the same repo.
prometheus.relabel "kubelet_filter" {
  max_cache_size = 100000

  rule {
    source_labels = ["__name__"]
    regex         = "up|scrape_samples_scraped|go_goroutines|kubelet_certificate_manager_client_expiration_renew_errors|kubelet_certificate_manager_client_ttl_seconds|kubelet_certificate_manager_server_ttl_seconds|kubelet_cgroup_manager_duration_seconds_bucket|kubelet_cgroup_manager_duration_seconds_count|kubelet_node_config_error|kubelet_node_name|kubelet_pleg_relist_duration_seconds_bucket|kubelet_pleg_relist_duration_seconds_count|kubelet_pleg_relist_interval_seconds_bucket|kubelet_pod_start_duration_seconds_bucket|kubelet_pod_start_duration_seconds_count|kubelet_pod_worker_duration_seconds_bucket|kubelet_pod_worker_duration_seconds_count|kubelet_running_container_count|kubelet_running_containers|kubelet_running_pod_count|kubelet_running_pods|kubelet_runtime_operations_errors_total|kubelet_runtime_operations_total|kubelet_server_expiration_renew_errors|kubelet_volume_stats_available_bytes|kubelet_volume_stats_capacity_bytes|kubelet_volume_stats_inodes|kubelet_volume_stats_inodes_free|kubelet_volume_stats_inodes_used|kubelet_volume_stats_used_bytes|kubernetes_build_info|namespace_workload_pod|process_cpu_seconds_total|process_resident_memory_bytes|rest_client_requests_total|storage_operation_duration_seconds_count|storage_operation_errors_total|volume_manager_total_volumes"
    action        = "keep"
  }

  forward_to = [prometheus.remote_write.grafana_cloud.receiver]
}

// ---- kube-state-metrics: needed for the dotdc dashboards' cluster/namespace/pod
// template variables (kube_node_info, kube_pod_info) and object-level state ----
discovery.kubernetes "kube_state_metrics" {
  role = "pod"
  namespaces {
    names = ["kube-state-metrics"]
  }
}

discovery.relabel "kube_state_metrics" {
  targets = discovery.kubernetes.kube_state_metrics.targets

  rule {
    source_labels = ["__meta_kubernetes_pod_label_app_kubernetes_io_name"]
    regex         = "kube-state-metrics"
    action        = "keep"
  }
  rule {
    source_labels = ["__meta_kubernetes_pod_container_port_number"]
    regex         = "8080"
    action        = "keep"
  }
}

prometheus.scrape "kube_state_metrics" {
  targets          = discovery.relabel.kube_state_metrics.output
  job_name         = "integrations/kubernetes/kube-state-metrics"
  scrape_interval  = "60s"
  forward_to       = [prometheus.relabel.kube_state_metrics_filter.receiver]
}

// Same allowlist approach as cadvisor/kubelet above.
// Source: allowLists/kube-state-metrics.yaml in github.com/grafana/k8s-monitoring-helm.
prometheus.relabel "kube_state_metrics_filter" {
  max_cache_size = 100000

  rule {
    source_labels = ["__name__"]
    regex         = "up|scrape_samples_scraped|kube_configmap_info|kube_configmap_metadata_resource_version|kube_cronjob_.*|kube_daemonset_.*|kube_deployment_metadata_generation|kube_deployment_spec_replicas|kube_deployment_status_condition|kube_deployment_status_observed_generation|kube_deployment_status_replicas_available|kube_deployment_status_replicas_updated|kube_horizontalpodautoscaler_spec_max_replicas|kube_horizontalpodautoscaler_spec_min_replicas|kube_horizontalpodautoscaler_status_current_replicas|kube_horizontalpodautoscaler_status_desired_replicas|kube_job_.*|kube_namespace_status_phase|kube_node_.*|kube_persistentvolume_status_phase|kube_persistentvolumeclaim_access_mode|kube_persistentvolumeclaim_info|kube_persistentvolumeclaim_labels|kube_persistentvolumeclaim_resource_requests_storage_bytes|kube_persistentvolumeclaim_status_phase|kube_pod_completion_time|kube_pod_container_info|kube_pod_container_resource_limits|kube_pod_container_resource_requests|kube_pod_container_status_last_terminated_reason|kube_pod_container_status_last_terminated_timestamp|kube_pod_container_status_restarts_total|kube_pod_container_status_waiting_reason|kube_pod_info|kube_pod_owner|kube_pod_restart_policy|kube_pod_spec_volumes_persistentvolumeclaims_info|kube_pod_start_time|kube_pod_status_phase|kube_pod_status_reason|kube_pod_init_.*|kube_replicaset_.*|kube_resourcequota|kube_secret_metadata_resource_version|kube_statefulset_.*"
    action        = "keep"
  }

  forward_to = [prometheus.remote_write.grafana_cloud.receiver]
}

// ---- node-exporter: host-level CPU/RAM/network/filesystem, needed for the
// dotdc Global/Nodes dashboards' $job and $instance variables (node_cpu_seconds_total,
// node_uname_info) which kube-state-metrics/cadvisor don't provide ----
discovery.kubernetes "node_exporter" {
  role = "pod"
  namespaces {
    names = ["node-exporter"]
  }
}

discovery.relabel "node_exporter" {
  targets = discovery.kubernetes.node_exporter.targets

  rule {
    source_labels = ["__meta_kubernetes_pod_label_app_kubernetes_io_name"]
    regex         = "prometheus-node-exporter"
    action        = "keep"
  }
  rule {
    source_labels = ["__meta_kubernetes_pod_container_port_number"]
    regex         = "9100"
    action        = "keep"
  }
}

prometheus.scrape "node_exporter" {
  targets          = discovery.relabel.node_exporter.output
  job_name         = "integrations/kubernetes/node-exporter"
  scrape_interval  = "60s"
  forward_to       = [prometheus.relabel.node_exporter_filter.receiver]
}

// Deliberately narrower than the dashboards could use: only what's actually
// load-bearing for basic node health (CPU, load, RAM, disk/net throughput+errors)
// plus the two identity metrics ($instance/$job variables need them). Dropped as
// avoidable: context switches, interrupts, conntrack, file descriptors, NTP/timex,
// packet counts, disk IOPS, per-core throttling - niche, rarely acted on here.
prometheus.relabel "node_exporter_filter" {
  max_cache_size = 100000

  rule {
    source_labels = ["__name__"]
    regex         = "up|scrape_samples_scraped|node_uname_info|node_boot_time_seconds|node_cpu_seconds_total|node_load1|node_load5|node_load15|node_memory_MemTotal_bytes|node_memory_MemAvailable_bytes|node_memory_SwapTotal_bytes|node_memory_SwapFree_bytes|node_filesystem_avail_bytes|node_filesystem_size_bytes|node_disk_read_bytes_total|node_disk_written_bytes_total|node_network_receive_bytes_total|node_network_transmit_bytes_total|node_network_receive_drop_total|node_network_transmit_drop_total|node_network_receive_errs_total|node_network_transmit_errs_total"
    action        = "keep"
  }
  // Only real block devices, not loop/dm/partitions (mirrors the cadvisor filter above)
  rule {
    source_labels = ["__name__", "device"]
    separator     = "@"
    regex         = "node_disk_.*@(mmcblk.p.+|nvme.+|rbd.+|sd.+|vd.+|xvd.+|dasd.+)"
    target_label  = "__keepme"
    replacement   = "1"
  }
  rule {
    source_labels = ["__name__", "__keepme"]
    separator     = "@"
    regex         = "node_disk_.*@"
    action        = "drop"
  }
  rule {
    source_labels = ["__name__"]
    regex         = "node_disk_.*"
    target_label  = "__keepme"
    replacement   = ""
  }
  // Only real filesystems, not tmpfs/overlay/proc/sysfs mounts
  rule {
    source_labels = ["__name__", "fstype"]
    separator     = "@"
    regex         = "node_filesystem_.*@(ext[234]|xfs|btrfs|zfs|vfat|ntfs)"
    target_label  = "__keepme"
    replacement   = "1"
  }
  rule {
    source_labels = ["__name__", "__keepme"]
    separator     = "@"
    regex         = "node_filesystem_.*@"
    action        = "drop"
  }
  rule {
    source_labels = ["__name__"]
    regex         = "node_filesystem_.*"
    target_label  = "__keepme"
    replacement   = ""
  }
  // Only real interfaces, not veth/cni/docker/loopback
  rule {
    source_labels = ["__name__", "device"]
    separator     = "@"
    regex         = "node_network_.*@(en[ospx][0-9].*|wlan[0-9].*|eth[0-9].*)"
    target_label  = "__keepme"
    replacement   = "1"
  }
  rule {
    source_labels = ["__name__", "__keepme"]
    separator     = "@"
    regex         = "node_network_.*@"
    action        = "drop"
  }
  rule {
    source_labels = ["__name__"]
    regex         = "node_network_.*"
    target_label  = "__keepme"
    replacement   = ""
  }

  forward_to = [prometheus.remote_write.grafana_cloud.receiver]
}

prometheus.remote_write "grafana_cloud" {
  // Adds a "cluster" label to every series. The dotdc dashboards' $cluster
  // variable (label_values(kube_node_info, cluster)) and per-panel
  // cluster="$cluster" filters need this - nothing upstream sets it otherwise.
  external_labels = {
    cluster = "home-lab",
  }

  endpoint {
    url = env("GRAFANA_CLOUD_PROMETHEUS_URL")

    basic_auth {
      username = env("GRAFANA_CLOUD_PROMETHEUS_USERNAME")
      password = env("GRAFANA_CLOUD_API_KEY")
    }
  }
}

// ---- Logs: tail every pod's logs via the Kubernetes API ----
discovery.kubernetes "pods" {
  role = "pod"
}

discovery.relabel "pod_logs" {
  targets = discovery.kubernetes.pods.targets

  rule {
    source_labels = ["__meta_kubernetes_namespace"]
    target_label  = "namespace"
  }
  rule {
    source_labels = ["__meta_kubernetes_pod_name"]
    target_label  = "pod"
  }
  rule {
    source_labels = ["__meta_kubernetes_pod_container_name"]
    target_label  = "container"
  }
}

loki.source.kubernetes "pod_logs" {
  targets    = discovery.relabel.pod_logs.output
  forward_to = [loki.write.grafana_cloud.receiver]
}

loki.write "grafana_cloud" {
  endpoint {
    url = env("GRAFANA_CLOUD_LOKI_URL")

    basic_auth {
      username = env("GRAFANA_CLOUD_LOKI_USERNAME")
      password = env("GRAFANA_CLOUD_API_KEY")
    }
  }
}

